// List returns one page of records under parent.
func (r *GraphQLRatePlanRepository) List(ctx context.Context, parent string, in repox.ListInput) ([]*rate_planv1.RatePlan, string, error) {
	parentIDs, err := repox.SplitName(parent, "hotels")
	if err != nil {
		return nil, "", err
	}
	// AIP-159: "-" for the parent reads across every parent.
	if parentIDs[len(parentIDs)-1] == "-" {
		return r.list(ctx, in)
	}
	return r.list(ctx, in, resourceql.HotelId.Eq(parentIDs[len(parentIDs)-1]))
}

