// graphQLBatch is Batch on GraphQL: queued writes go into the Unit's mutation
// request on Commit (see repox.Unit.Commit). A guarded UpdateOutputOnly runs
// ahead of it, one by one: the engine reports its failed guard by touching no
// row, which cannot abort a request.
type graphQLBatch struct {
	u         *repox.Unit
	svc       *otaql.Service
	retention time.Duration
	// keys holds the row key of every record this batch creates, by name: a
	// later write in the batch finds its row here, since it is not stored
	// until the batch's request runs.
	keys map[string]string
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *graphQLBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// rowID returns the row key of the record named name: one this batch creates,
// else what resolve (a repository's rowID) finds.
func (b *graphQLBatch) rowID(ctx context.Context, name string, resolve func(context.Context, string) (string, error)) (string, error) {
	if id, ok := b.keys[name]; ok {
		return id, nil
	}
	return resolve(ctx, name)
}

// CreateRatePlan queues a create and returns the name the record will have.
func (b *graphQLBatch) CreateRatePlan(parent string, in *rate_planv1.RatePlan) (string, error) {
	r := &GraphQLRatePlanRepository{Svc: b.svc}
	ci, named, err := r.newInput(parent, in)
	if err != nil {
		return "", err
	}
	if b.keys == nil {
		b.keys = map[string]string{}
	}
	b.keys[named.GetName()] = ci.Id
	queueRatePlanReferences(b.u, named, nil)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		return r.insertOps(ctx, ops, named, ci)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/RatePlan", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdateRatePlan queues Update; in.Etag, when set, guards it inside the
// batch's request (see updateOps).
func (b *graphQLBatch) UpdateRatePlan(in *rate_planv1.RatePlan, paths []string) {
	if _, err := repox.SplitName(in.GetName(), "hotels", "ratePlans"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLRatePlanRepository{Svc: b.svc}
	queueRatePlanReferences(b.u, in, paths)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		return r.updateOps(ctx, ops, id, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/RatePlan", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getRatePlan)})
}

// UpdateRatePlanWithOutputOnly queues UpdateWithOutputOnly; in.Etag, when
// set, guards it inside the batch's request, as UpdateRatePlan's does.
func (b *graphQLBatch) UpdateRatePlanWithOutputOnly(in *rate_planv1.RatePlan, paths, outputPaths []string) {
	if _, err := repox.SplitName(in.GetName(), "hotels", "ratePlans"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLRatePlanRepository{Svc: b.svc}
	queueRatePlanReferences(b.u, in, paths)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		return r.updateOps(ctx, ops, id, in, paths, outputPaths)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/RatePlan", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getRatePlan)})
}

// UpdateRatePlanOutputOnly queues UpdateOutputOnly; in.Etag, when set, guards
// it, and a guarded update runs ahead of the batch (see graphQLBatch).
func (b *graphQLBatch) UpdateRatePlanOutputOnly(in *rate_planv1.RatePlan, paths []string) {
	if len(paths) == 0 {
		b.u.Fail(fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument))
		return
	}
	if _, err := repox.SplitName(in.GetName(), "hotels", "ratePlans"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLRatePlanRepository{Svc: b.svc}
	patch := ratePlanToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/RatePlan", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getRatePlan)})
	if etag := in.GetEtag(); etag != "" {
		b.u.QueueGraphQLAhead(func(ctx context.Context) error {
			id, err := b.rowID(ctx, in.GetName(), r.rowID)
			if err != nil {
				return err
			}
			_, err = b.svc.Mutation.Rateplan.Resource.UpdateIfMatch(ctx, id, patch, resourceql.Etag.Eq(etag))
			return mapGraphQLErr(err)
		})
		return
	}
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Rateplan.Resource.UpdateOp(id, patch, new(resourceql.UpdateRateplanResourceByIdResponse)))
		return nil, nil
	})
}

// DeleteRatePlan queues a soft delete. A record already deleted or gone is
// not an error.
func (b *graphQLBatch) DeleteRatePlan(name string) {
	if _, err := repox.SplitName(name, "hotels", "ratePlans"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLRatePlanRepository{Svc: b.svc, Retention: b.retention}
	queueRatePlanDelete(b.u, name, false)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Rateplan.Resource.UpdateOp(id, r.deletePatch(), new(resourceql.UpdateRateplanResourceByIdResponse), resourceql.Update().PreCheck(resourceql.DeleteTime.IsNull(true))))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/RatePlan", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getRatePlan)})
}

// PurgeRatePlan queues the record's removal for good. A record already
// gone is not an error.
func (b *graphQLBatch) PurgeRatePlan(name string) {
	if _, err := repox.SplitName(name, "hotels", "ratePlans"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLRatePlanRepository{Svc: b.svc}
	// A record a referrer in another database or service names is kept, as
	// Purge keeps it. One a foreign key of this database still names fails
	// the commit with repox.ErrForeignKey: the request is one transaction,
	// and the engine cannot skip one of its mutations.
	keep := queueRatePlanPurge(b.u, name)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		if *keep {
			return nil, nil
		}
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		return r.purgeOps(ctx, ops, id)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/RatePlan", Name: name, Op: repox.ChangePurge, LoadPrior: repox.PriorOf(name, getRatePlan)})
}
